package com.nlespam.models

object BleDatabase {
    data class CompanyInfo(
        val name: String,
        val manufacturerIds: Set<Int>,
        val ouis: Set<String>
    )

    private val manufacturerMap: Map<Int, String> by lazy {
        val map = mutableMapOf<Int, String>()
        companies.forEach { company ->
            company.manufacturerIds.forEach { id -> map[id] = company.name }
        }
        map
    }

    private val ouiMap: Map<String, String> by lazy {
        val map = mutableMapOf<String, String>()
        companies.forEach { company ->
            company.ouis.forEach { oui -> map[oui.uppercase()] = company.name }
        }
        map
    }

    fun getCompanyName(manufacturerId: Int?, address: String?): String? {
        if (manufacturerId != null) {
            val name = manufacturerMap[manufacturerId]
            if (name != null) return name
        }
        if (address != null && address.length >= 8) {
            val oui = address.take(8).uppercase()
            val name = ouiMap[oui]
            if (name != null) return name
        }
        return null
    }

